#!/bin/bash

# Create simple colored PNG icons using base64
# These are minimal 32x32 PNG files with solid colors

ICONS_DIR="/Users/siddharthbalaji/Documents/MustangMaps/frontend/calpoly-map/assets/icons"

# Blue water fountain icon (32x32 blue circle)
echo "" | base64 -d > "$ICONS_DIR/water-fountain.png"

# Purple bathroom icon (32x32 purple circle)
echo "" | base64 -d > "$ICONS_DIR/bathroom.png"

# Orange printer icon (32x32 orange circle)
echo "" | base64 -d > "$ICONS_DIR/printer.png"

# Pink favorites icon (32x32 pink circle)
echo "" | base64 -d > "$ICONS_DIR/favorites.png"

echo "Created placeholder icons in $ICONS_DIR"
ls -lh "$ICONS_DIR"
